import { tv, type VariantProps } from "@/lib/beton/tv";

/** Scramble, typewriter and counter share one plain typographic surface. */
export const textEffect = tv({
  base: "font-display font-black tracking-tight text-foreground tabular-nums",
  variants: {
    size: {
      sm: "text-h4",
      md: "text-h3",
      lg: "text-h2",
      xl: "text-h1",
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export const typewriter = tv({
  slots: {
    root: "font-display font-black tracking-tight text-foreground",
    caret: "ml-0.5 inline-block w-[0.6ch] bg-foreground align-baseline motion-safe:animate-blink",
  },
  variants: {
    size: {
      sm: { root: "text-h4", caret: "h-[1em]" },
      md: { root: "text-h3", caret: "h-[1em]" },
      lg: { root: "text-h2", caret: "h-[1em]" },
      xl: { root: "text-h1", caret: "h-[1em]" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export const glitchText = tv({
  slots: {
    root: "relative inline-block font-display font-black tracking-tight text-foreground",
    layer: "pointer-events-none absolute inset-0 select-none",
    body: "relative",
    a: "text-primary motion-safe:animate-glitch-a motion-reduce:hidden",
    b: "text-danger motion-safe:animate-glitch-b motion-reduce:hidden",
  },
  variants: {
    size: {
      sm: { root: "text-h4" },
      md: { root: "text-h3" },
      lg: { root: "text-h2" },
      xl: { root: "text-h1" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type TextEffectVariants = VariantProps<typeof textEffect>;
export type TypewriterVariants = VariantProps<typeof typewriter>;
export type GlitchTextVariants = VariantProps<typeof glitchText>;

"use client";

import { textEffect, type TextEffectVariants } from "@/lib/beton/recipes/text-effects.recipe";
import { visuallyHidden } from "@/lib/beton/shared";
import { useEffect, useRef, useState, type ComponentProps } from "react";
import { useReducedMotion } from "@/lib/beton/use-reduced-motion";

export interface CounterProps extends Omit<ComponentProps<"span">, "children">, TextEffectVariants {
  /** The number to land on. */
  value: number;
  /** Where to start counting. */
  from?: number;
  /** How long the count takes, in milliseconds. */
  duration?: number;
  /** How the number is written. Also used for the value screen readers get. */
  format?: Intl.NumberFormatOptions;
  /** Which locale formats the number. */
  locale?: string;
  /** Text before and after the number, such as a currency sign or a unit. */
  prefix?: string;
  suffix?: string;
}

/**
 * A number that counts up in hard steps. Screen readers are given the final
 * number straight away, and reduced motion skips the count.
 */
export function Counter({
  size = "md",
  value,
  from = 0,
  duration = 1200,
  format,
  locale,
  prefix = "",
  suffix = "",
  className,
  ...props
}: CounterProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = useState(from);
  const frame = useRef(0);

  useEffect(() => {
    if (reduced || duration <= 0) {
      setShown(value);
      return;
    }
    const start = performance.now();
    const step = (now: number) => {
      const progress = Math.min(1, (now - start) / duration);
      // Stepped, not eased: the number lands on twenty stops along the way.
      const stepped = Math.round(progress * 20) / 20;
      setShown(from + (value - from) * stepped);
      if (progress < 1) frame.current = requestAnimationFrame(step);
      else setShown(value);
    };
    frame.current = requestAnimationFrame(step);
    return () => cancelAnimationFrame(frame.current);
  }, [duration, from, reduced, value]);

  const formatter = new Intl.NumberFormat(locale, format);
  const label = `${prefix}${formatter.format(value)}${suffix}`;

  return (
    <span {...props} className={textEffect({ size, class: className })}>
      <span aria-hidden="true">
        {prefix}
        {formatter.format(Number.isInteger(value) ? Math.round(shown) : shown)}
        {suffix}
      </span>
      <span className={visuallyHidden}>{label}</span>
    </span>
  );
}
